function firstName(name) {
  return String(name || 'cliente').trim().split(/\s+/)[0] || 'cliente';
}
function norm(value) {
  return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const data = $json;
const text = norm(data.message_text);
const nome = firstName(data.customer_name);
let reply = '';
if (/\b(token|cartao|cartao|a3|safesign|leitora)\b/.test(text)) {
  reply = 'Entendi, ' + nome + '. O token esta conectado no computador e aparece alguma mensagem de erro na tela?';
} else if (/\b(a1|arquivo|pfx|p12|instalar certificado|importar certificado)\b/.test(text)) {
  reply = 'Entendi, ' + nome + '. Voce ja abriu o Assistente de Certificado Digital da Safeweb e em qual etapa apareceu o erro? https://instalacaocertificado-acsafeweb.safewebpss.com.br/';
} else if (/\b(e-cac|ecac|receita|govbr|gov\.br)\b/.test(text)) {
  reply = 'Entendi, ' + nome + '. Quando voce entra no e-CAC, o certificado aparece para selecionar no navegador?';
} else if (/\b(video|videoconferencia|videoconferencia|validacao|validacao)\b/.test(text)) {
  reply = 'Entendi, ' + nome + '. Esse atendimento e para primeiro certificado ou renovacao?';
} else if (/\b(driver|download|baixar|instalador)\b/.test(text)) {
  reply = 'Entendi, ' + nome + '. Para drivers de token da Safeweb, acesse pelo computador: https://www.safeweb.com.br/centraldedownloads/token';
} else {
  reply = 'Entendi, ' + nome + '. Me diga qual mensagem de erro aparece ou em qual etapa voce travou para eu te orientar pelo caminho certo.';
}
return [{ json: { ...data, reply_text: reply, reply_subject: 'Suporte CertiID', event_type: 'automation.support', entity_type: 'crm_chat_conversations' } }];
